function datedQuestion(rng, list) {
  const e = pick(rng, list); const others = shuffle(rng, [...new Set(list.filter((x) => x.year !== e.year).map((x) => x.year))]).slice(0, 2);
  return { type: 'choice', story: `${e.event}.`, prompt: 'When?', choices: shuffle(rng, [e.year, ...others]), answer: e.year, explain: `${e.event}: ${e.year}.\n${e.why}`, visual: null, explainVisual: null };
}
function datedFact(rng, list) {
  const e = pick(rng, list); const others = shuffle(rng, list.filter((x) => x.year !== e.year)).slice(0, 2).map((x) => x.event);
  return { type: 'choice', story: `${e.year}.`, prompt: 'What happened then?', choices: shuffle(rng, [e.event, ...others]), answer: e.event, explain: `${e.year}: ${lowerTitle(e.event)}.\n${e.why}`, visual: null, explainVisual: null };
}
